static void test_q3_bmp(void) {
  uint8_t bytes[54 + 6];
  memset(bytes, 0, sizeof bytes);
  bytes[0] = 66; bytes[1] = 77;
  put_u32_le(bytes + 2, sizeof bytes);
  put_u32_le(bytes + 18, 2);            /* width */
  put_u32_le(bytes + 22, 1);            /* height */
  put_u16_le(bytes + 28, 24);           /* bits per pixel (after planes) */
  bytes[54] = 30; bytes[55] = 20; bytes[56] = 10;
  bytes[57] = 60; bytes[58] = 50; bytes[59] = 40;
  qa_image_data image;
  CHECK(qa_decode_q3_bmp(bytes, sizeof bytes, NULL, &image) == 1);
  static const uint8_t want[8] = {10, 20, 30, 255, 40, 50, 60, 255};
  CHECK(bytes_equal(image.pixels, image.pixels_length, want, sizeof want));
  qa_image_data_destroy(&image);
  /* The source `&&` ID check: one wrong byte still decodes. */
  bytes[0] = 0;
  CHECK(qa_decode_q3_bmp(bytes, sizeof bytes, NULL, &image) == 1);
  qa_image_data_destroy(&image);
  bytes[1] = 0;
  CHECK_ABORTS(qa_decode_q3_bmp(bytes, sizeof bytes, NULL, &image));
}

static void test_q3_pcx(void) {
  uint8_t indices[4] = {1, 200, 3, 4};
  uint8_t palette[768];
  for (int i = 0; i < 768; i++) palette[i] = (uint8_t)(i & 255);
  qa_indexed_image source = {2, 2, indices, sizeof indices};
  size_t length = 0;
  uint8_t *encoded = qa_encode_pcx(&source, palette, sizeof palette, &length);
  CHECK(encoded != NULL);
  qa_q3_pcx_indexed decoded;
  char *rejection = NULL;
  CHECK(qa_decode_q3_pcx_indexed(encoded, length, NULL, &decoded, &rejection) == 1);
  CHECK(bytes_equal(decoded.indices, decoded.indices_length, indices, sizeof indices));
  CHECK(bytes_equal(decoded.palette, decoded.palette_length, palette, sizeof palette));
  qa_image_data expanded;
  CHECK(qa_expand_q3_pcx(&decoded, &expanded) == 1);
  CHECK(expanded.pixels[0] == 3 && expanded.pixels[3] == 255);
  qa_image_data_destroy(&expanded);
  qa_q3_pcx_indexed_destroy(&decoded);
  uint8_t bad[16] = {0};
  CHECK(qa_decode_q3_pcx_indexed(bad, sizeof bad, NULL, &decoded, &rejection) == -1);
  CHECK(rejection != NULL && strstr(rejection, "Bad pcx file") != NULL);
  free(rejection);
  free(encoded);
}

static char warning_text[256];
static void capture_warning(void *ctx, const char *text) {
  (void)ctx;
  snprintf(warning_text, sizeof warning_text, "%s", text);
}

static void test_q3_tga_rle_and_warning(void) {
  uint8_t bytes[18 + 1 + 3] = {0, 0, 10, 0, 0, 0, 0, 0, 0, 0, 0, 0,
                               2, 0, 1, 0, 24, 0x20, 0x81, 1, 2, 3};
  warning_text[0] = '\0';
  qa_image_data image;
  CHECK(qa_decode_q3_tga(bytes, sizeof bytes, "x.tga", capture_warning, NULL,
                         &image) == 1);
  static const uint8_t want[8] = {3, 2, 1, 255, 3, 2, 1, 255};
  CHECK(bytes_equal(image.pixels, image.pixels_length, want, sizeof want));
  CHECK(strstr(warning_text, "top-down") != NULL);
  qa_image_data_destroy(&image);
}

static void test_tga_indexed_rle(void) {
  uint8_t bytes[18 + 6 + 1 + 3];
  memset(bytes, 0, sizeof bytes);
  bytes[1] = 1;          /* map type */
  bytes[2] = 9;          /* RLE color-mapped */
  put_u16_le(bytes + 5, 2);   /* map length */
  bytes[7] = 24;         /* map depth */
  put_u16_le(bytes + 12, 3);
  put_u16_le(bytes + 14, 1);
  bytes[16] = 8;         /* depth */
  bytes[17] = 32;        /* top origin */
  bytes[18] = 10; bytes[19] = 20; bytes[20] = 30; /* BGR -> RGB 30,20,10 */
  bytes[21] = 40; bytes[22] = 50; bytes[23] = 60;
  bytes[24] = 2;         /* raw packet, 3 pixels */
  bytes[25] = 0; bytes[26] = 1; bytes[27] = 0;
  qa_tga_image image;
  CHECK(qa_decode_tga(bytes, sizeof bytes, NULL, &image) == 1);
  static const uint8_t want[12] = {30, 20, 10, 255, 60, 50, 40, 255, 30, 20, 10, 255};
  CHECK(bytes_equal(image.level.pixels.bytes, image.level.pixels.length, want,
                    sizeof want));
  CHECK(image.has_indexed == 1 && image.indices[0] == 0 && image.indices[1] == 1 &&
        image.indices[2] == 0);
  qa_tga_image_destroy(&image);
}

static void test_indexed_formats(void) {
  /* qpic */
  uint8_t qpic[8 + 2];
  put_u32_le(qpic, 2); put_u32_le(qpic + 4, 1);
  qpic[8] = 5; qpic[9] = 6;
  qa_indexed_image decoded_qpic;
  CHECK(qa_decode_qpic(qpic, sizeof qpic, NULL, &decoded_qpic) == 1);
  CHECK(decoded_qpic.width == 2 && decoded_qpic.indices[0] == 5 &&
        decoded_qpic.indices[1] == 6);
  qa_indexed_image_destroy(&decoded_qpic);
  /* Q1 miptex embedded 16x16 */
  size_t mip_length = 40 + 256 + 64 + 16 + 4;
  uint8_t *mip = (uint8_t *)calloc(1, mip_length);
  memcpy(mip, "tex", 3);
  put_u32_le(mip + 16, 16); put_u32_le(mip + 20, 16);
  put_u32_le(mip + 24, 40); put_u32_le(mip + 28, 296);
  put_u32_le(mip + 32, 360); put_u32_le(mip + 36, 376);
  memset(mip + 40, 1, 256); memset(mip + 296, 2, 64);
  memset(mip + 360, 3, 16); memset(mip + 376, 4, 4);
  qa_q1_miptex texture;
  CHECK(qa_decode_q1_mip_texture(mip, mip_length, NULL, &texture) == 1);
  CHECK(texture.kind == QA_Q1_MIP_EMBEDDED && strcmp(texture.name, "tex") == 0);
  CHECK(texture.levels[3].pixels.length == 4 && texture.levels[3].pixels.bytes[0] == 4);
  qa_q1_miptex_destroy(&texture);
  put_u32_le(mip + 24, 0); put_u32_le(mip + 28, 0);
  put_u32_le(mip + 32, 0); put_u32_le(mip + 36, 0);
  CHECK(qa_decode_q1_mip_texture(mip, mip_length, NULL, &texture) == 1);
  CHECK(texture.kind == QA_Q1_MIP_EXTERNAL);
  qa_q1_miptex_destroy(&texture);
  free(mip);
  /* WAL 8x8 */
  size_t wal_length = 100 + 64 + 16 + 4 + 1;
  uint8_t *wal = (uint8_t *)calloc(1, wal_length);
  memcpy(wal, "wal", 3);
  put_u32_le(wal + 32, 8); put_u32_le(wal + 36, 8);
  put_u32_le(wal + 40, 100); put_u32_le(wal + 44, 164);
  put_u32_le(wal + 48, 180); put_u32_le(wal + 52, 184);
  memcpy(wal + 56, "next", 4);
  put_u32_le(wal + 88, 3); put_u32_le(wal + 92, 4); put_u32_le(wal + 96, 5);
  memset(wal + 100, 9, 64);
  qa_wal_image wal_image;
  CHECK(qa_decode_wal(wal, wal_length, NULL, &wal_image) == 1);
  CHECK(wal_image.flags == 3 && wal_image.contents == 4 && wal_image.value == 5);
  CHECK(strcmp(wal_image.animation, "next") == 0);
  CHECK(wal_image.levels[0].pixels.length == 64 &&
        wal_image.levels[0].pixels.bytes[0] == 9);
  CHECK(wal_image.levels[3].width == 1);
  qa_wal_image_destroy(&wal_image);
  free(wal);
}

static void test_wad(void) {
  /* header(12) + qpic(10) + palette(768) + raw(1) + dir(3*32) */
  size_t total = 12 + 10 + 768 + 1 + 96;
  uint8_t *wad = (uint8_t *)calloc(1, total);
  memcpy(wad, "WAD2", 4);
  put_u32_le(wad + 4, 3);
  put_u32_le(wad + 8, 12 + 10 + 768 + 1);
  uint8_t *at = wad + 12;
  put_u32_le(at, 2); put_u32_le(at + 4, 1); at[8] = 5; at[9] = 6;
  for (int i = 0; i < 768; i++) wad[22 + i] = (uint8_t)(i & 255);
  wad[790] = 9;
  uint8_t *dir = wad + 791;
  put_u32_le(dir, 12); put_u32_le(dir + 4, 10); put_u32_le(dir + 8, 10);
  dir[12] = 66; memcpy(dir + 16, "PIC", 3);
  put_u32_le(dir + 32, 22); put_u32_le(dir + 36, 768); put_u32_le(dir + 40, 768);
  dir[44] = 64; memcpy(dir + 48, "PALETTE", 7);
  put_u32_le(dir + 64, 790); put_u32_le(dir + 68, 1); put_u32_le(dir + 72, 1);
  dir[76] = 1; memcpy(dir + 80, "RAW", 3);
  qa_wad_archive archive;
  CHECK(qa_decode_wad(wad, total, NULL, &archive) == 1);
  CHECK(strcmp(archive.kind, "WAD2") == 0 && archive.lump_count == 3);
  CHECK(strcmp(archive.lumps[0].name, "pic") == 0);
  qa_wad_image image;
  CHECK(qa_decode_wad_image(&archive, &archive.lumps[0], NULL, &image) == 1);
  CHECK(image.kind == QA_WAD_IMAGE_QPIC && image.image.indices[1] == 6);
  qa_wad_image_destroy(&image);
  CHECK(qa_decode_wad_image(&archive, &archive.lumps[1], NULL, &image) == 1);
  CHECK(image.kind == QA_WAD_IMAGE_PALETTE && image.colors_length == 768);
  qa_wad_image_destroy(&image);
  CHECK(qa_decode_wad_image(&archive, &archive.lumps[2], NULL, &image) == 1);
  CHECK(image.kind == QA_WAD_IMAGE_RAW && image.lump == &archive.lumps[2]);
  qa_wad_image_destroy(&image);
  qa_wad_archive_destroy(&archive);
  free(wad);
}

int main(void) {
  test_bsp_kind();
  test_pcx_roundtrip();
  test_png_tga_screenshots();
  test_png_fixtures();
  test_jpeg_solid();
  test_jpeg_fixtures();
  test_palette();
  test_lit_and_mip();
  test_gif();
  test_bmp_fixtures();
  test_q3_bmp();
  test_q3_pcx();
  test_q3_tga_rle_and_warning();
  test_tga_indexed_rle();
  test_indexed_formats();
  test_wad();
  if (failures == 0) {
    printf("test_images: all %d checks passed\n", checks);
    return 0;
  }
  fprintf(stderr, "test_images: %d of %d checks failed\n", failures, checks);
  return 1;
}
